CREATE OR REPLACE FUNCTION public.save_influencer_program(_id uuid,_contract text DEFAULT NULL,_goals jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ip influencer_programs; g jsonb; months int[]; BEGIN SELECT * INTO ip FROM influencer_programs WHERE id=_id FOR UPDATE; IF auth.uid() IS NULL OR ip.id IS NULL OR NOT can_view_client(ip.client_id) OR NOT EXISTS(SELECT 1 FROM pipelines p WHERE p.code='influencer' AND is_pipeline_head(auth.uid(),p.id)) THEN RAISE EXCEPTION 'Assigned Influencer Program Head only'; END IF; IF client_on_hold(ip.client_id) THEN RAISE EXCEPTION 'This client is on hold'; END IF; IF _goals IS NOT NULL THEN IF ip.status<>'approved' THEN RAISE EXCEPTION 'Owner must approve the contract before goals are set'; END IF; IF jsonb_typeof(_goals)<>'array' OR jsonb_array_length(_goals)<>3 THEN RAISE EXCEPTION 'Enter goals for 3, 6 and 12 months'; END IF; FOR g IN SELECT value FROM jsonb_array_elements(_goals) LOOP IF coalesce((g->>'months')::int,0) NOT IN(3,6,12) OR coalesce(trim(g->>'influencers'),'')='' OR coalesce((g->>'visits')::int,0)<1 THEN RAISE EXCEPTION 'Each goal needs influencers and at least one visit'; END IF; END LOOP; SELECT array_agg((value->>'months')::int ORDER BY (value->>'months')::int) INTO months FROM jsonb_array_elements(_goals); IF months<>ARRAY[3,6,12] THEN RAISE EXCEPTION 'Enter one goal each for 3, 6 and 12 months'; END IF; UPDATE influencer_programs SET goals=_goals,updated_at=now() WHERE id=_id; ELSE IF coalesce(trim(_contract),'') !~ '^https://' AND NOT (trim(_contract) LIKE ip.client_id::text||'/influencer/%' AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='client-files' AND name=trim(_contract))) THEN RAISE EXCEPTION 'Add a secure contract link or uploaded file'; END IF; UPDATE influencer_programs SET contract_url=trim(_contract),status='pending',approved_by=NULL,approved_at=NULL,goals='[]',updated_at=now() WHERE id=_id; END IF; END $$;